<node CREATED="1285711785330" ID="Freemind_Link_1642155934" MODIFIED="1285711798537" TEXT="F&#xe1;bricas de Software">
<node CREATED="1285711805404" FOLDED="true" ID="_" MODIFIED="1285711953114" POSITION="right" TEXT="Desarrollo de Software dirigido por modelos (DSDM o MDD)">
<hook NAME="accessories/plugins/NodeNote.properties">
<text>Model Driven Development</text>
</hook>
<node CREATED="1285713887500" ID="Freemind_Link_1454577980" MODIFIED="1285713896238" TEXT="Introducci&#xf3;n">
<node CREATED="1285711959385" ID="Freemind_Link_1493648300" MODIFIED="1285712060719" TEXT="Es una propuesta para el desarrollo de software en la que se atribuye a los modelos el papel principal de todo el proceso, frente a propuestas tradicionales basadas en lenguajes de programaci&#xf3;n y plataformas de objetos y componentes de software"/>
<node CREATED="1285712083846" ID="Freemind_Link_427832529" MODIFIED="1285712093792" TEXT="Razones de su aparici&#xf3;n:">
<node CREATED="1285712094887" ID="Freemind_Link_537381290" MODIFIED="1285712192903" TEXT="La creciente complejidad de las aplicaciones software, que han de satisfacer un mayor n&#xfa;mero de requisitos (heterogeneidad, distribuci&#xf3;n, alta disponibilidad, adaptabilidad, etc.)"/>
<node CREATED="1285712209259" ID="Freemind_Link_677304434" MODIFIED="1285712275783" TEXT="Las nuevas tecnolog&#xed;as evolucionan demasiado deprisa (COM, DCOM, COM+, CORBA, CCM, J2EE, .NET, Web Services, SOA)">
<node CREATED="1285712296769" ID="Freemind_Link_874619548" MODIFIED="1285712339670" TEXT="Hace que las inversiones en tecnolog&#xed;as concretas sean demasiado vol&#xe1;tiles"/>
</node>
</node>
<node CREATED="1285712603745" ID="Freemind_Link_1771188985" MODIFIED="1288566535635" TEXT="Hubo otros intentos de solucionar el problema:">
<node CREATED="1285712617651" ID="Freemind_Link_1765207755" MODIFIED="1285712709392" TEXT="Definici&#xf3;n de lenguajes de programaci&#xf3;n de m&#xe1;s alto nivel (COBOL, Pascal, C, C++, Eiffel, Java, Python, Ruby)"/>
<node CREATED="1285713625367" ID="Freemind_Link_493005086" MODIFIED="1285713674819" TEXT="Aparici&#xf3;n de nuevas t&#xe9;cnicas y mecanismos">
<node CREATED="1285713689333" ID="Freemind_Link_758038676" MODIFIED="1285713717867" TEXT="Software frameworks (Struts y Rails)"/>
</node>
<node CREATED="1285713733114" ID="Freemind_Link_850797055" MODIFIED="1285713797186" TEXT="Una raz&#xf3;n de su aparente fracaso es que estaban basados en sus propias tecnolog&#xed;as del software, cuando ah&#xed; es donde residen los principales problemas"/>
</node>
</node>
<node CREATED="1285713918723" ID="Freemind_Link_1967609965" MODIFIED="1285713928491" TEXT="Origen del DSDM">
<node CREATED="1285714034499" ID="Freemind_Link_1155113269" MODIFIED="1285714129005" TEXT="En la d&#xe9;cada de los 90 exist&#xed;a un consenso de que las herramientas, t&#xe9;cnicas y abstracciones de programaci&#xf3;n no eran las m&#xe1;s adecuadas para la demanda de aplicaciones software"/>
<node CREATED="1285714145313" ID="Freemind_Link_957532408" MODIFIED="1285714187778" TEXT="Un 80% del coste asociado a un sistema inform&#xe1;tico estaba destinado a la construcci&#xf3;n del mismo"/>
<node CREATED="1285714209936" ID="Freemind_Link_26344591" MODIFIED="1285714230702" TEXT="Se origin&#xf3; el nacimiento de 2 nuevas filosof&#xed;as:">
<node CREATED="1285714237525" ID="Freemind_Link_1235513218" MODIFIED="1285862543720" TEXT="Ingenier&#xed;a de Software asistida por ordenador (CASE)">
<icon BUILTIN="full-1"/>
</node>
<node CREATED="1285714280901" ID="Freemind_Link_36306904" MODIFIED="1285862546552" TEXT="Lenguajes de Cuarta Generaci&#xf3;n (4GL)">
<icon BUILTIN="full-2"/>
</node>
<node CREATED="1285714378315" ID="Freemind_Link_1010525613" MODIFIED="1285714495052" TEXT="Ambas propuestas trataron de dar soporte en el control de la complejidad de los proyectos software, proporcionando los mecanismos adecuados para una mejor comprensi&#xf3;n de los modelos que describen la empresa, sus actividades y el desarrollo de los sistemas de informaci&#xf3;n"/>
<node CREATED="1285714568315" ID="Freemind_Link_1187899225" MODIFIED="1285862591210" TEXT="Buscaban automatizar el proceso de construcci&#xf3;n"/>
</node>
<node CREATED="1285714619382" ID="Freemind_Link_848574370" MODIFIED="1285714639320" TEXT="Nace una 3ra iniciativa">
<node CREATED="1285714640699" ID="Freemind_Link_292402450" MODIFIED="1285714664569" TEXT="Dise&#xf1;o orientado a objetos (DOO)">
<node CREATED="1285714668022" ID="Freemind_Link_1885567015" MODIFIED="1285714726540" TEXT="La naturaleza del DOO se fundamenta en 3 pilares conceptuales del dise&#xf1;o de software">
<node CREATED="1285714728012" ID="Freemind_Link_1544699193" MODIFIED="1285862585641" TEXT="Abstracci&#xf3;n">
<icon BUILTIN="full-1"/>
<node CREATED="1285714740640" ID="Freemind_Link_1145260049" MODIFIED="1285714773246" TEXT="Consistente en captar las caracter&#xed;sticas y el comportamiento esenciales de un objeto"/>
</node>
<node CREATED="1285714786965" ID="Freemind_Link_700614105" MODIFIED="1285862601258" TEXT="Ocultamiento">
<icon BUILTIN="full-2"/>
<node CREATED="1285714793259" ID="Freemind_Link_1182299473" MODIFIED="1285714856051" TEXT="Capacidad para omitir los detalles internos del comportamiento de un objeto y exponer s&#xf3;lo los detalles que sean necesarios para el resto del sistema"/>
</node>
<node CREATED="1285714883045" ID="Freemind_Link_441064365" MODIFIED="1285862605058" TEXT="Encapsulaci&#xf3;n">
<icon BUILTIN="full-3"/>
<node CREATED="1285714891976" ID="Freemind_Link_1304970477" MODIFIED="1285714909325" TEXT="Derivada de las dos propiedades anteriores"/>
</node>
<node CREATED="1285714924416" ID="Freemind_Link_1001864480" MODIFIED="1285714958738" TEXT="Estos 3 pilares procuran favorecer un objetivo b&#xe1;sico: la reutilizaci&#xf3;n del software"/>
</node>
</node>
</node>
<node CREATED="1285714995903" ID="Freemind_Link_197014160" MODIFIED="1285715035264" TEXT="La orientaci&#xf3;n a objetos no ha cubierto todas las expectativas fijadas inicialmente"/>
<node CREATED="1285715044989" ID="Freemind_Link_1772629236" MODIFIED="1285715076612" TEXT="Ha logrado reemplazar los lenguajes procedimentales empleados hasta ese momento"/>
<node CREATED="1285715094714" ID="Freemind_Link_907239651" MODIFIED="1285715156398" TEXT="Ni las metodolog&#xed;as CASE ni las herramientas CASE han terminado de implantarse en el mercado inform&#xe1;tico seg&#xfa;n las previsiones iniciales"/>
<node CREATED="1285715346921" ID="Freemind_Link_893882573" MODIFIED="1285715399229" TEXT="Tras la llegada de UML, la industria del software sufre una nueva revoluci&#xf3;n">
<node CREATED="1285715439918" ID="Freemind_Link_1516071476" MODIFIED="1285715538870" TEXT="Los vendedores de herramientas se vuelcan en el desarrollo de herramientas basadas en modelos siguiendo una filosof&#xed;a round-trip"/>
<node CREATED="1285715543272" ID="Freemind_Link_574972655" MODIFIED="1285715590669" TEXT="Salen las primeras herramientas UML y los IDE (Integrated Development Environment)">
<node CREATED="1285715615846" ID="Freemind_Link_1966475468" MODIFIED="1285715730700" TEXT="La mayor&#xed;a de estos IDE tan s&#xf3;lo llegaban a generar el esqueleto de la implementaci&#xf3;n partiendo de un conjunto de modelos, utilizando plantillas predeterminadas por la herramienta"/>
<node CREATED="1285715778135" ID="Freemind_Link_1204382526" MODIFIED="1285715994473" TEXT="Con el tiempo estas propuestas han evolucionado hasta proveer sofisticados asistentes, que facilitan la tarea del programador para la construcci&#xf3;n de interfaces de usuario y la implementaci&#xf3;n de la l&#xf3;gica de negocios basada en el uso probado de patrones y depurado de patrones de dise&#xf1;o y esqueletos de c&#xf3;digo"/>
</node>
<node CREATED="1285716042334" ID="Freemind_Link_984322328" MODIFIED="1285716150315" TEXT="Estas herramientas siguen sin ser capaces de propagar autom&#xe1;ticamente las implicaciones que un cambio en un patr&#xf3;n de dise&#xf1;o origina sobre el c&#xf3;digo ya generado"/>
<node CREATED="1285716184619" ID="Freemind_Link_515886472" MODIFIED="1285716248178" TEXT="En apariencia existe un alto grado de sincronizaci&#xf3;n entre los diagramas y la implementaci&#xf3;n del sistema">
<node CREATED="1285716254482" ID="Freemind_Link_338604422" MODIFIED="1285716345423" TEXT="Un an&#xe1;lisis nos revela que, en la mayor&#xed;a de casos, los modelos no son m&#xe1;s que una mera representaci&#xf3;n gr&#xe1;fica del c&#xf3;digo generado">
<node CREATED="1285716391151" ID="Freemind_Link_710688131" MODIFIED="1285716422930" TEXT="Resta beneficio al tiempo al tiempo invertido en el modelado del sistema"/>
<node CREATED="1285716425445" ID="Freemind_Link_1779100486" MODIFIED="1285716471057" TEXT="Reduce la productividad y los beneficios de la empresa de desarrollo"/>
<node CREATED="1285716506942" ID="Freemind_Link_1362114254" MODIFIED="1285716546939" TEXT="S&#xf3;lo proporciona un mecanismo para producir documentaci&#xf3;n atractiva"/>
</node>
</node>
</node>
<node CREATED="1285716596049" ID="Freemind_Link_1206740382" MODIFIED="1285716667376" TEXT="El DSDM nace por tanto con el objetivo de cubrir estas debilidades, integrando modelos y c&#xf3;digo como los principales participantes en el proceso productivo de software"/>
</node>
<node CREATED="1285716781805" ID="Freemind_Link_1575367035" MODIFIED="1285716800765" TEXT="Desarrollo de software dirigido por modelos">
<node CREATED="1285716820087" ID="Freemind_Link_1464409420" MODIFIED="1285716849805" TEXT="Es preciso, abordar 2 perspectivas claramente diferenciadas:">
<node CREATED="1285716851239" ID="Freemind_Link_1832207003" MODIFIED="1285716923415" TEXT="La perspectiva que trata de los aspectos relativos al dominio de la aplicaci&#xf3;n (dominio del problema)">
<icon BUILTIN="full-1"/>
<node CREATED="1285717060983" ID="Freemind_Link_1726802979" MODIFIED="1285717126067" TEXT="Normalmente no tiene nada que ver con la tecnolog&#xed;a software"/>
<node CREATED="1285717133539" ID="Freemind_Link_1585143934" MODIFIED="1285862716502" TEXT="Para el usuario, el software es una mera herramienta que no debe preocuparse"/>
</node>
<node CREATED="1285716926970" ID="Freemind_Link_941984980" MODIFIED="1285717046256" TEXT="La perspectiva que trata los aspectos relativos a la tecnolog&#xed;a software utilizada para implementar el sistema (dominio de la soluci&#xf3;n)">
<icon BUILTIN="full-2"/>
</node>
</node>
<node CREATED="1285717210347" ID="Freemind_Link_1255779510" MODIFIED="1285717318733" TEXT="El proceso de desarrollo de software consiste en la capacidad de representar adecuadamente el dominio del problema, para posteriormente transformar esa representaci&#xf3;n en lo que se constituir&#xed;a su implementaci&#xf3;n para una tecnolog&#xed;a concreta, es decir, en el dominio de la soluci&#xf3;n">
<node CREATED="1285717384568" FOLDED="true" ID="Freemind_Link_93253858" MODIFIED="1285717479443" TEXT="Es donde aparece DSDM, convierte a los modelos y a las transformaciones entre ellos en los principales artefactos de todas las fases del proceso de desarrollo de software">
<node CREATED="1285717480707" ID="Freemind_Link_1781992108" MODIFIED="1285717501290" TEXT="Captura y gesti&#xf3;n de los requisitos"/>
<node CREATED="1285717502188" ID="Freemind_Link_772977881" MODIFIED="1285717504900" TEXT="Dise&#xf1;o"/>
<node CREATED="1285717506662" ID="Freemind_Link_664852784" MODIFIED="1285717510120" TEXT="An&#xe1;lisis"/>
<node CREATED="1285717510910" ID="Freemind_Link_1412918186" MODIFIED="1285717520209" TEXT="Implementaci&#xf3;n"/>
<node CREATED="1285717521338" ID="Freemind_Link_32911196" MODIFIED="1285717525276" TEXT="Despliegue"/>
<node CREATED="1285717533211" ID="Freemind_Link_1042528750" MODIFIED="1285717542429" TEXT="Configuraci&#xf3;n"/>
<node CREATED="1285717543345" ID="Freemind_Link_56033775" MODIFIED="1285717546430" TEXT="Mantenimiento"/>
<node CREATED="1285717547223" ID="Freemind_Link_1937385484" MODIFIED="1285717552037" TEXT="Evoluci&#xf3;n"/>
</node>
</node>
<node CREATED="1285717818802" ID="Freemind_Link_1050064566" MODIFIED="1285717831860" TEXT="Definici&#xf3;n">
<node CREATED="1285717565805" ID="Freemind_Link_63393326" MODIFIED="1285717785440" TEXT="DSDM podria definirse como una estrategia para el desarrollo de sistemas software basada en la separaci&#xf3;n conceptual entre la especificaci&#xf3;n funcional de un sistema y su implementaci&#xf3;n, en la que tanto los modelos como las transformaciones adquieren un mayor grado de independencia y relevancia en el proceso de desarrollo de software"/>
</node>
<node CREATED="1285717873109" ID="Freemind_Link_1996690605" MODIFIED="1285717954026" TEXT="El &#xe9;xito de esta iniciativa ha originado la evoluci&#xf3;n de distintos paradigmas englobados dentro de DSDM">
<node CREATED="1285717972015" ID="Freemind_Link_1719518207" MODIFIED="1285718302446" TEXT="Algunas de estas propuestas son:">
<node CREATED="1285718013740" ID="Freemind_Link_1517367582" MODIFIED="1285718021532" TEXT="La iniciativa de MDA"/>
<node CREATED="1285718022221" ID="Freemind_Link_1775272069" MODIFIED="1285718067728" TEXT="Las t&#xe9;cnicas de AMDD (Agile Model-Driven Development)"/>
<node CREATED="1285718085704" ID="Freemind_Link_1473836723" MODIFIED="1285718114836" TEXT="Las propuestas de DSM (Domain Specific Modeling)"/>
<node CREATED="1285718186459" ID="Freemind_Link_1874357189" MODIFIED="1285718227559" TEXT="Las estrategias de DOP (Domain-Oriented Programming)"/>
<node CREATED="1285718243815" ID="Freemind_Link_538889648" MODIFIED="1285718271401" TEXT="Las SF (Software Factories)"/>
</node>
<node CREATED="1285718310813" ID="Freemind_Link_1694795541" MODIFIED="1285718427441" TEXT="Todas estas propuestas comparten una serie de principios b&#xe1;sicos">
<arrowlink DESTINATION="Freemind_Link_284405276" ENDARROW="Default" ENDINCLINATION="1078;0;" ID="Freemind_Arrow_Link_1883083998" STARTARROW="None" STARTINCLINATION="1078;0;"/>
</node>
</node>
<node CREATED="1285718371793" ID="Freemind_Link_284405276" MODIFIED="1285720352295" TEXT="Principios b&#xe1;sicos de DSDM">
<icon BUILTIN="full-1"/>
<node CREATED="1285718454653" ID="Freemind_Link_1523773220" MODIFIED="1285718460193" TEXT="Modelo">
<node CREATED="1285718461103" ID="Freemind_Link_1071238270" MODIFIED="1285718479747" TEXT="T&#xe9;rmino clave en la filosof&#xed;a del DSDM"/>
<node CREATED="1285718480408" ID="Freemind_Link_1577854396" MODIFIED="1285718753988" TEXT="Es una abstracci&#xf3;n simplificada de un sistema o concepto del mundo real"/>
<node CREATED="1285718549587" ID="Freemind_Link_1519832198" MODIFIED="1285718607683" TEXT="Contiene un menor nivel de detalle que su correspondiente artefacto de la vida real"/>
<node CREATED="1285718623632" ID="Freemind_Link_256368271" MODIFIED="1285718643930" TEXT="Dentro del &#xe1;mbito de la Ingenier&#xed;a del Software y DSDM">
<node CREATED="1285718645464" ID="Freemind_Link_1210204409" MODIFIED="1285718681315" TEXT="Es una descripci&#xf3;n de un sistema, o parte de &#xe9;ste, escrito en un lenguaje bien definido"/>
<node CREATED="1285718682272" ID="Freemind_Link_108071121" MODIFIED="1285718720806" TEXT="Es una representaci&#xf3;n de una parte de la funcionalidad, estructura y/o comportamiento de un sistema"/>
<node CREATED="1285718760592" ID="Freemind_Link_818056291" MODIFIED="1285718854459" TEXT="Es una descripci&#xf3;n o especificaci&#xf3;n de un sistema y su entorno definido para cierto prop&#xf3;sito. Un modelo es representado habitualmente como una combinaci&#xf3;n de elementos gr&#xe1;ficos y de texto"/>
<node CREATED="1285718905540" ID="Freemind_Link_432282178" MODIFIED="1285719040289" TEXT="Se centra en la descripci&#xf3;n de un &#xfa;nico aspecto de un sistema, de acuerdo a un prop&#xf3;sito espec&#xed;fico, y descrito hasta un cierto nivel de abstracci&#xf3;n adecuado para el problema modelado, haciendo uso generalmente de lenguajes de modelado cuya sem&#xe1;ntica est&#xe1; bien definida"/>
</node>
</node>
<node CREATED="1285719268125" FOLDED="true" ID="Freemind_Link_285407300" MODIFIED="1285719358233" TEXT="La idea compartida de todos los paradigmas englobados dentro del DSDM es la conveniencia de utilizar para el modelado lenguajes de mayor nivel de abstracci&#xf3;n que los lenguajes de programaci&#xf3;n habituales">
<node CREATED="1285719373292" ID="Freemind_Link_467730491" MODIFIED="1285719635866" TEXT="Lenguajes que manejen conceptos m&#xe1;s cercanos al dominio de la aplicaci&#xf3;n"/>
<node CREATED="1285719412425" FOLDED="true" ID="Freemind_Link_408972939" MODIFIED="1285719445327" TEXT="Dependiendo del &#xe1;mbito DSDM, estos lenguajes se denominan:">
<node CREATED="1285719459139" ID="Freemind_Link_1419916485" MODIFIED="1285719640864" TEXT="Lenguajes de modelado (MDA)"/>
<node CREATED="1285719471471" ID="Freemind_Link_630886693" MODIFIED="1285719501472" TEXT="Lenguajes espec&#xed;ficos del dominio (DSM y SF)"/>
</node>
</node>
<node CREATED="1285719556015" ID="Freemind_Link_93075791" MODIFIED="1285719640865" TEXT="La t&#xe9;cnica del metamodelado es una estrategia muy seguida en la actualidad para la definici&#xf3;n de lenguajes de modelado">
<arrowlink DESTINATION="Freemind_Link_1419916485" ENDARROW="Default" ENDINCLINATION="576;0;" ID="Freemind_Arrow_Link_1745519255" STARTARROW="None" STARTINCLINATION="576;0;"/>
</node>
<node CREATED="1285719694964" FOLDED="true" ID="Freemind_Link_1327258099" MODIFIED="1285720448220" TEXT="Metamodelo">
<hook NAME="accessories/plugins/NodeNote.properties">
<text>Para comprender bien estos conceptos es necesario revisar el ejemplo y las ilustraciones del libro</text>
</hook>
<node CREATED="1285719700853" ID="Freemind_Link_1730945104" MODIFIED="1285719826076" TEXT="Especifica los conceptos del lenguaje, las relaciones entre ellos  y las reglas estructurales que restringen los posibles elementos del modelo, as&#xed; como aquellas combinaciones entre elementos que respetan las reglas sem&#xe1;nticas del dominio"/>
<node CREATED="1285719854583" ID="Freemind_Link_297389601" MODIFIED="1285719956219" TEXT="Cada modelo se escribe en el lenguaje que define su metamodelo (lenguaje de modelado), quedando establecida la relaci&#xf3;n entre el modelo y su metamodelo por una relaci&#xf3;n de dependencia etiquetada con el nombre &quot;conforme a&quot;"/>
<node CREATED="1285719981481" ID="Freemind_Link_1834431896" MODIFIED="1285720033088" TEXT="Los metamodelos son a su vez modelos, por tanto, est&#xe1;n escritos igualmente en el lenguaje definido por su meta-metamodelo"/>
<node CREATED="1285720097677" ID="Freemind_Link_705244913" MODIFIED="1285735917897" TEXT="El procedimiento recursivo de definir modelos &quot;conforme a&quot; otros modelos de mayor grado de abstracci&#xf3;n acaba cuando se alcanza el nivel de meta-metamodelo, ya que los meta-metamodelos se dice son conformes a ellos mismos"/>
</node>
</node>
<node CREATED="1285720473904" FOLDED="true" ID="Freemind_Link_880322183" MODIFIED="1285720491627" TEXT="Lenguajes de modelado">
<icon BUILTIN="full-2"/>
<node CREATED="1285720616492" FOLDED="true" ID="Freemind_Link_621815068" MODIFIED="1285720745205" TEXT="Se ha utilizado tradicionalmente para representar modelos de un sistema software consiste en el uso de diagramas o representaciones gr&#xe1;ficas">
<node CREATED="1285720765538" FOLDED="true" ID="Freemind_Link_1937281620" MODIFIED="1285720798846" TEXT="En muchos casos, estas representaciones son bastante informales">
<node CREATED="1285720800100" ID="Freemind_Link_222828961" MODIFIED="1285720835467" TEXT="Limitando su aplicabilidad e interpretaci&#xf3;n en determinados contextos"/>
</node>
<node CREATED="1285720869527" FOLDED="true" ID="Freemind_Link_562492024" MODIFIED="1285720934519" TEXT="Esta imprecisi&#xf3;n y ambig&#xfc;edad provoca que la representaci&#xf3;n no pueda ser objeto de an&#xe1;lisis">
<node CREATED="1285720935726" ID="Freemind_Link_1775256230" MODIFIED="1285720968379" TEXT="No resulta posible predecir ni derivar ning&#xfa;n tipo de c&#xf3;digo para el sistema modelado"/>
</node>
<node CREATED="1285720997713" ID="Freemind_Link_185613235" MODIFIED="1285721045092" TEXT="Existen otras notaciones gr&#xe1;ficas definidas de forma m&#xe1;s precisa"/>
<node CREATED="1285721045862" ID="Freemind_Link_1893113993" MODIFIED="1285721122195" TEXT="Suele esconderse un proceso previo consistente en la definici&#xf3;n formal y precisa del lenguaje de modelado"/>
</node>
<node CREATED="1285721153011" FOLDED="true" ID="Freemind_Link_664709591" MODIFIED="1285721212531" TEXT="Criterios que establecen caracter&#xed;sticas que deber&#xed;a verificar un lenguaje de modelado">
<node CREATED="1285721214144" ID="Freemind_Link_760158648" MODIFIED="1285735991591" TEXT="El prop&#xf3;sito del lenguaje de modelado tiene que ser claro y expl&#xed;citamente especificado">
<icon BUILTIN="full-1"/>
</node>
<node CREATED="1285721271950" ID="Freemind_Link_1068599908" MODIFIED="1285735996985" TEXT="Sus conceptos deben corresponderse con los del dominio y, por tanto, poder ser f&#xe1;cilmente reconocidos por los usuarios">
<icon BUILTIN="full-2"/>
</node>
<node CREATED="1285721340707" ID="Freemind_Link_1431444455" MODIFIED="1285736019874" TEXT="El uso de su notaci&#xf3;n (tanto gr&#xe1;fica como textual) tiene que ser sencillo">
<icon BUILTIN="full-3"/>
</node>
<node CREATED="1285721383919" ID="Freemind_Link_1063730533" MODIFIED="1285736029046" TEXT="El lenguaje tiene que definir un conjunto de reglas, que hacen posible el uso de herramientas que validen expresiones, modelos y ayuden al usuario durante el proceso del dise&#xf1;o">
<icon BUILTIN="full-4"/>
</node>
<node CREATED="1285721465733" ID="Freemind_Link_1080745907" MODIFIED="1285736032787" TEXT="La sem&#xe1;ntica del lenguaje tambi&#xe9;n debe estar definida de forma precisa y no ambigua, de modo que los usuarios puedan construir modelos que otros usuarios o herramientas ser&#xe1;n capaces de entender, validar y procesar">
<icon BUILTIN="full-5"/>
</node>
</node>
<node CREATED="1285721850429" ID="Freemind_Link_104630628" MODIFIED="1285862798748" TEXT="UML incumple el primero de los criterios se&#xf1;alados">
<arrowlink DESTINATION="Freemind_Link_760158648" ENDARROW="Default" ENDINCLINATION="724;0;" ID="Freemind_Arrow_Link_591479783" STARTARROW="None" STARTINCLINATION="724;0;"/>
</node>
<node CREATED="1285721664298" ID="Freemind_Link_223109250" MODIFIED="1285721823092" TEXT="UML se puede utilizar para especificar la mayor&#xed;a de los sistemas basados en objetos o en componentes y modelar aplicaciones de muy diversos dominios de aplicaci&#xf3;n (telecomunicaciones, comercio, sanidad, etc.) y plataformas de objetos distribuidos (J2EE, .NET, CORBA, etc.)"/>
<node CREATED="1285721919888" ID="Freemind_Link_1242790741" MODIFIED="1285722412945" TEXT="El hecho de que UML sea un lenguaje de prop&#xf3;sito general proporciona una gran flexibilidad y expresividad a la hora de modelar sistemas"/>
<node CREATED="1285722012419" FOLDED="true" ID="Freemind_Link_619848382" MODIFIED="1285722048951" TEXT="DSL (Domain Specific Language)">
<node CREATED="1285722050174" ID="Freemind_Link_1122308899" MODIFIED="1285722100883" TEXT="Es m&#xe1;s espec&#xed;fico para modelar  y representar los conceptos de ciertos dominios de aplicaci&#xf3;n"/>
<node CREATED="1285722104445" ID="Freemind_Link_38802500" MODIFIED="1285722167081" TEXT="Tienden a soportar abstracciones de mayor nivel que los lenguajes de modelado de prop&#xf3;sito general"/>
<node CREATED="1285722167898" ID="Freemind_Link_897907942" MODIFIED="1285722212485" TEXT="Los conceptos definidos son m&#xe1;s cercanos al dominio del problema que al dominio de la soluci&#xf3;n"/>
<node CREATED="1285722221679" ID="Freemind_Link_1949132784" MODIFIED="1285722289682" TEXT="DSL sigue las abstracciones y sem&#xe1;ntica del dominio que representa, explicitando las reglas del dominio como restricciones del propio lenguaje"/>
<node CREATED="1285722309312" FOLDED="true" ID="Freemind_Link_921211781" MODIFIED="1285722323011" TEXT="Implica al menos 2 tareas b&#xe1;sicas">
<node CREATED="1285722323828" ID="Freemind_Link_1980095853" MODIFIED="1285722363610" TEXT="La definici&#xf3;n de los conceptos y reglas del dominio (la sintaxis abstracta)"/>
<node CREATED="1285722364957" ID="Freemind_Link_62855277" MODIFIED="1285722394490" TEXT="La definici&#xf3;n de la notaci&#xf3;n usada  para representarlos (la sintaxis concreta)"/>
</node>
<node CREATED="1285722437224" ID="Freemind_Link_1214535192" MODIFIED="1285722504884" TEXT="Un DSL bien definido es un poderoso lenguaje de implementaci&#xf3;n, que aporta m&#xe1;s rigor que un lenguaje de modelado de prop&#xf3;sito general"/>
<node CREATED="1285722517915" ID="Freemind_Link_1252353128" MODIFIED="1285722690275" TEXT="Las correspondencias entre un DSL y un lenguaje de programaci&#xf3;n son similares a las existentes entre un lenguaje como Java y su c&#xf3;digo binario"/>
<node CREATED="1285722916384" FOLDED="true" ID="Freemind_Link_996617227" MODIFIED="1285722990626" TEXT="Existen herramientas que asisten al dise&#xf1;ador en varios de los aspectos relacionados con el modelado de sistemas utilizando DSL">
<node CREATED="1285722999399" FOLDED="true" ID="Freemind_Link_1575990426" MODIFIED="1285723071925" TEXT="Estas herramientas denominadas &quot;entornos de DSM&quot; pueden ser consideradas  como &quot;herramientas de metamodelado&quot;">
<node CREATED="1285723073460" ID="Freemind_Link_25461541" MODIFIED="1285723109196" TEXT="Herramientas de modelado que sirven para definir otras herramientas de modelado"/>
</node>
<node CREATED="1285723118609" FOLDED="true" ID="Freemind_Link_432980676" MODIFIED="1285723140888" TEXT="Como ejemplos de entornos de DSM">
<node CREATED="1285723141845" ID="Freemind_Link_557815679" LINK="http://www.metacase.com/mep" MODIFIED="1285863500336" TEXT="MetaEdit+ (www.metacase.com/mep)"/>
<node CREATED="1285723176251" ID="Freemind_Link_1728528377" LINK="http://www.eclipse.org/gmt/gems" MODIFIED="1285863125829" TEXT="GEMS (Generic Eclipse Modeling System, www.eclipse.org/gmt/gems)"/>
<node CREATED="1285723257316" ID="Freemind_Link_1611440768" LINK="http://www.isis.vanderbilt.edu/projects/gme" MODIFIED="1285863679756" TEXT="GME (Generic Modelling System, www.isis.vanderbilt.edu/projects/gme)"/>
</node>
<node CREATED="1285723329817" FOLDED="true" ID="Freemind_Link_54279707" MODIFIED="1285723411173" TEXT="La popularidad de estas herramientas ha propiciado que este tipo de herramientas se hayan incluido en entornos integrados de desarrollo">
<node CREATED="1285723415750" ID="Freemind_Link_1327664719" MODIFIED="1285723443208" TEXT="EMP (Eclipse Modelling Project)"/>
<node CREATED="1285723444197" ID="Freemind_Link_352411285" MODIFIED="1285723511614" TEXT="Herramientas de Microsoft para SF"/>
</node>
</node>
</node>
</node>
</node>
<node CREATED="1285723536861" FOLDED="true" ID="Freemind_Link_1649803014" MODIFIED="1285736161904" TEXT="Arquitectura dirigida por modelos (MDA)">
<node CREATED="1285736121322" ID="Freemind_Link_1829904813" MODIFIED="1285736239662" TEXT="Es una de las iniciativas m&#xe1;s conocidas de DSDM, una estrategia de desarrollo software propuesta y esponsorizada por el consorcio OMG"/>
<node CREATED="1285736329257" FOLDED="true" ID="Freemind_Link_1739676321" MODIFIED="1285736334285" TEXT="OMG">
<node CREATED="1285736248245" ID="Freemind_Link_1023381431" MODIFIED="1285736320605" TEXT="Dicho consorcio est&#xe1; dedicado al cuidado y establecimiento de diversos est&#xe1;ndares sobre tecnolog&#xed;as orientadas a objetos, tales como UML, XMI o CORBA"/>
<node CREATED="1285736375575" FOLDED="true" ID="Freemind_Link_1708437555" MODIFIED="1285736436875" TEXT="Este grupo est&#xe1; constituido por compa&#xf1;&#xed;as y organizaciones con amplia experiencia en el desarrollo de software tales como:">
<node CREATED="1285736438097" ID="Freemind_Link_1288880034" MODIFIED="1285736440942" TEXT="HP"/>
<node CREATED="1285736441477" ID="Freemind_Link_1877552588" MODIFIED="1285736447550" TEXT="IBM"/>
<node CREATED="1285736448005" ID="Freemind_Link_1086582146" MODIFIED="1285736461074" TEXT="Sun Microsystems"/>
<node CREATED="1285736461407" ID="Freemind_Link_552572230" MODIFIED="1285736470681" TEXT="Apple Computer"/>
</node>
<node CREATED="1285736489797" FOLDED="true" ID="Freemind_Link_1070081495" MODIFIED="1285736524238" TEXT="Mantiene la marca registrada sobre:">
<node CREATED="1285736525216" ID="Freemind_Link_165169764" MODIFIED="1285736528022" TEXT="MDA"/>
<node CREATED="1285736529086" ID="Freemind_Link_476241661" MODIFIED="1285736564780" TEXT="MDD (DSDM)"/>
<node CREATED="1285736565927" ID="Freemind_Link_294358137" MODIFIED="1285736606549" TEXT="MDAD (Model Driven Application Development)"/>
<node CREATED="1285736647957" ID="Freemind_Link_1769109248" MODIFIED="1285736676181" TEXT="MBAD (Model Based Application Development)"/>
<node CREATED="1285736677270" ID="Freemind_Link_1548814423" MODIFIED="1285736696551" TEXT="MBP (Model Based Programming)"/>
</node>
<node CREATED="1285737072053" FOLDED="true" ID="Freemind_Link_576917193" MODIFIED="1285737101869" TEXT="Los est&#xe1;ndares de OMG incluyen:">
<node CREATED="1285737103062" ID="Freemind_Link_160350479" MODIFIED="1285737132546" TEXT="UML (Unified Modelling Language)"/>
<node CREATED="1285737133516" ID="Freemind_Link_1725958575" MODIFIED="1285737165448" TEXT="MOF (Meta-Object Facility)"/>
<node CREATED="1285737166159" ID="Freemind_Link_590771876" MODIFIED="1285737193954" TEXT="XMI (XML Metadata Interchange)"/>
<node CREATED="1285737195900" ID="Freemind_Link_1589219088" MODIFIED="1285737245596" TEXT="MOF/QVT (Query / View / Transformations)"/>
</node>
<node CREATED="1285737266631" ID="Freemind_Link_766363147" MODIFIED="1285737290514" TEXT="Accesible desde www.omg.org"/>
</node>
<node CREATED="1285736765810" FOLDED="true" ID="Freemind_Link_1333211648" MODIFIED="1285736769846" TEXT="MDE">
<node CREATED="1285736770892" ID="Freemind_Link_177996330" MODIFIED="1285736807060" TEXT="Acr&#xf3;nimo usado por la comunidad cient&#xed;fica que a&#xfa;n no ha sido depositado por OMG"/>
<node CREATED="1285736845232" ID="Freemind_Link_417791206" MODIFIED="1285736925732" TEXT="Usado por la comunidad cient&#xed;fica para hacer referencia a ideas relacionadas con la ingenier&#xed;a de modelos sin centrarse exclusivamente en los est&#xe1;ndares OMG"/>
<node CREATED="1285736945109" ID="Freemind_Link_1379481090" MODIFIED="1285736963351" TEXT="MDA no debe ser confundido con DSDM o MDE"/>
</node>
<node CREATED="1285736977661" ID="Freemind_Link_182042417" MODIFIED="1285737043563" TEXT="Es la puesta en pr&#xe1;ctica de OMG de DSDM, usando el sistema de herramientas y de est&#xe1;ndares definidos por OMG"/>
<node CREATED="1285737352601" FOLDED="true" ID="Freemind_Link_1531052563" MODIFIED="1285737363817" TEXT="El marco de MDA">
<icon BUILTIN="full-1"/>
<node CREATED="1285737368555" FOLDED="true" ID="Freemind_Link_1853866806" MODIFIED="1285737377256" TEXT="Tipos de modelos">
<node CREATED="1285737614330" FOLDED="true" ID="Freemind_Link_230895077" MODIFIED="1285737713647" TEXT="El marco de MDA se organiza b&#xe1;sicamente en torno a:">
<node CREATED="1285737715399" FOLDED="true" ID="Freemind_Link_556279301" MODIFIED="1285737758135" TEXT="Modelos independientes de plataforma (PIM)">
<node CREATED="1285737796757" ID="Freemind_Link_418410699" MODIFIED="1285737846296" TEXT="Es una especificaci&#xf3;n de un sistema que concreta sus requisitos funcionales en t&#xe9;rminos de conceptos del dominio"/>
<node CREATED="1285737921227" FOLDED="true" ID="Freemind_Link_584767399" MODIFIED="1285738004574" TEXT="Su representaci&#xf3;n est&#xe1; basada en un lenguaje espec&#xed;fico para el dominio modelado, donde los conceptos representados exhiben un cierto grado de independencia respecto a diversas plataformas">
<node CREATED="1285738020928" FOLDED="true" ID="Freemind_Link_839139096" MODIFIED="1285738036794" TEXT="Plataformas tecnol&#xf3;gicas">
<node CREATED="1285738037879" ID="Freemind_Link_1794187781" MODIFIED="1285738041734" TEXT="CORBA"/>
<node CREATED="1285738041991" ID="Freemind_Link_1194146378" MODIFIED="1285738044150" TEXT=".NET"/>
<node CREATED="1285738044473" ID="Freemind_Link_1201778266" MODIFIED="1285738049424" TEXT="J2EE"/>
</node>
<node CREATED="1285738059815" ID="Freemind_Link_278986702" MODIFIED="1285738069582" TEXT="Plataformas abstractas"/>
</node>
<node CREATED="1285738136421" ID="Freemind_Link_815772877" MODIFIED="1285738216449" TEXT="Es as&#xed; como MDA puede asegurar que el modelo independiente de la plataforma (PIM) sobrevivir&#xe1; a los cambios que se produzcan en futuras plataformas tecnol&#xf3;gicas y arquitecturas software"/>
</node>
<node CREATED="1285737758777" FOLDED="true" ID="Freemind_Link_827930075" MODIFIED="1285737764288" TEXT="Modelos espec&#xed;ficos de plataforma (PSM)">
<node CREATED="1285859439581" ID="Freemind_Link_513085722" MODIFIED="1285859577224" TEXT="El modelo PIM puede traducirse a uno o m&#xe1;s modelos espec&#xed;ficos de la plataforma PSM para la implementaci&#xf3;n correspondiente, usando lenguajes espec&#xed;ficos de dominio, o lenguajes de prop&#xf3;sito general como Java, C#, Python, etc."/>
<node CREATED="1285859610797" FOLDED="true" ID="Freemind_Link_1169367252" MODIFIED="1285859652826" TEXT="Los perfiles UML fueron la alternativa m&#xe1;s utilizada como lenguaje de modelado para crear modelos PIM y PSM">
<node CREATED="1285859653973" ID="Freemind_Link_293005864" MODIFIED="1285859684521" TEXT="Ahora han ganado aceptaci&#xf3;n otros lenguajes de metamodelado como MOF"/>
<node CREATED="1285859687532" FOLDED="true" ID="Freemind_Link_127496500" MODIFIED="1285859754454" TEXT="Un perfil UML, se define como una extensi&#xf3;n de un subconjunto de UML utilizando los conceptos que incorpora el mecanismo de extensi&#xf3;n de UML">
<node CREATED="1285859756001" ID="Freemind_Link_876508794" MODIFIED="1285859763243" TEXT="Estereotipos"/>
<node CREATED="1285859763626" ID="Freemind_Link_806379249" MODIFIED="1285859772331" TEXT="Restricciones"/>
<node CREATED="1285859772751" ID="Freemind_Link_1741284655" MODIFIED="1285859781221" TEXT="Valores etiquetados"/>
</node>
<node CREATED="1285859830854" ID="Freemind_Link_1692042312" MODIFIED="1285859873302" TEXT="En la actualidad existen perfiles adoptados por OMG para plataformas como CORBA, Java, EJB o C++"/>
</node>
</node>
<node CREATED="1285737770546" ID="Freemind_Link_613997723" MODIFIED="1285861070751" TEXT="Transformaciones entre modelos">
<arrowlink DESTINATION="Freemind_Link_1298877775" ENDARROW="Default" ENDINCLINATION="612;0;" ID="Freemind_Arrow_Link_660081625" STARTARROW="None" STARTINCLINATION="612;0;"/>
</node>
</node>
<node CREATED="1285738271827" FOLDED="true" ID="Freemind_Link_150460174" MODIFIED="1285738278818" TEXT="Plataforma">
<node CREATED="1285738279629" ID="Freemind_Link_609925445" MODIFIED="1285738406701" TEXT="Es un conjunto de subsistemas y tecnolog&#xed;as que describen la funcionalidad de una aplicaci&#xf3;n a trav&#xe9;s de interfaces y patrones espec&#xed;ficos, facilitando que cualquier sistema que vaya a ser implementado sobre dicha plataforma pueda hacer uso de estos recursos sin tener en consideraci&#xf3;n aquellos detalles que son relativos a la funcionalidad ofrecida por la plataforma concreta"/>
</node>
</node>
<node CREATED="1285737397754" FOLDED="true" ID="Freemind_Link_1298877775" MODIFIED="1285861070749" TEXT="Transformaciones">
<node CREATED="1285859900638" ID="Freemind_Link_1513574433" MODIFIED="1285859932543" TEXT="Es el proceso de convertir un modelo de un sistema en otro modelo del mismo sistema"/>
<node CREATED="1285859936053" ID="Freemind_Link_601332619" MODIFIED="1285859985078" TEXT="Establece un conjunto de reglas que describen c&#xf3;mo un modelo expresado en un lenguaje origen puede ser transformado en un modelo en un lenguaje destino"/>
<node CREATED="1285859994975" FOLDED="true" ID="Freemind_Link_1503118298" MODIFIED="1285860013943" TEXT="Para definir una transformaci&#xf3;n entre modelos es necesario:">
<node CREATED="1285860014776" ID="Freemind_Link_861724117" MODIFIED="1285860048676" TEXT="Seleccionar el tipo de transformaci&#xf3;n y lenguaje de definici&#xf3;n para transformaciones a utilizar"/>
<node CREATED="1285860052420" ID="Freemind_Link_565807793" MODIFIED="1285860092996" TEXT="Seleccionar la herramienta CASE para MDA que nos permita implementar los modelos y las transformaciones de forma autom&#xe1;tica"/>
</node>
<node CREATED="1285860125469" FOLDED="true" ID="Freemind_Link_1898062096" MODIFIED="1285860144160" TEXT="MDA describe una variedad de transformaciones entre modelos">
<node CREATED="1285860145177" FOLDED="true" ID="Freemind_Link_306046886" MODIFIED="1285860160964" TEXT="Mappings verticales (refinamientos)">
<node CREATED="1285860163850" ID="Freemind_Link_927288069" MODIFIED="1285860196234" TEXT="Relacionan modelos del sistema situados en distintos niveles de abstracci&#xf3;n"/>
<node CREATED="1285860197050" ID="Freemind_Link_1420667184" MODIFIED="1285860298520" TEXT="Pueden aplicarse tanto en sentido descendente (transformaci&#xf3;n de PIM a PSM) como en sentido ascendente (de PSM a PIM), sientos &#xe9;stos &#xfa;ltimos el resultado de aplicar un procesos de ingenier&#xed;a inversa"/>
<node CREATED="1285860307256" ID="Freemind_Link_414802447" MODIFIED="1285860342836" TEXT="No suponen una aportaci&#xf3;n nueva dentro del proceso de desarrollo de MDA"/>
<node CREATED="1285860356242" FOLDED="true" ID="Freemind_Link_884149264" MODIFIED="1285860428734" TEXT="La mayor&#xed;a de herramientas que proporcionan opciones para la generaci&#xf3;n de c&#xf3;digo incluyen reglas de transformaci&#xf3;n (mappings verticales)">
<node CREATED="1285860446779" ID="Freemind_Link_393290111" MODIFIED="1285860507574" TEXT="Ese m&#xf3;dulo permanece oculto al usuario, por tanto sin posibilidad de ser modificado o manipulado por &#xe9;ste"/>
</node>
<node CREATED="1285860538359" ID="Freemind_Link_1886536597" MODIFIED="1285860574600" TEXT="No es apropiado ligar el dise&#xf1;o de un modelo a una plataforma particular"/>
<node CREATED="1285860585800" ID="Freemind_Link_596106883" MODIFIED="1285860637559" TEXT="Resulta cr&#xed;tico hacer que las reglas de transformaci&#xf3;n entre modelos sean dependientes de la herramienta CASE en cuesti&#xf3;n"/>
</node>
<node CREATED="1285860672930" FOLDED="true" ID="Freemind_Link_18476733" MODIFIED="1285860680122" TEXT="Mappings horizontales">
<node CREATED="1285860680937" ID="Freemind_Link_458121706" MODIFIED="1285860732455" TEXT="Relacionan o integran los modelos que cubren diversos aspectos o dominios dentro de un sistema considerados al mismo nivel de abstracci&#xf3;n"/>
<node CREATED="1285860781218" ID="Freemind_Link_1045713084" MODIFIED="1285860873684" TEXT="Mantienen la consistencia entre los distintos niveles y garantizan que la informaci&#xf3;n modelada sobre una entidad en un modelo es consistente con lo que se dice sobre dicha entidad en cualquier otra especificaci&#xf3;n situada al mismo nivel de abstracci&#xf3;n"/>
</node>
</node>
</node>
<node CREATED="1285737409247" FOLDED="true" ID="Freemind_Link_240667486" MODIFIED="1285737418327" TEXT="Tipos de transformaciones">
<node CREATED="1285861142462" ID="Freemind_Link_1941641145" MODIFIED="1285861214233" TEXT="Una forma de facilitar la transformaci&#xf3;n entre modelos es la identificaci&#xf3;n de elementos en el PIM que deban transformarse de forma concreta para la plataforma de destino, y marcarlos como tal"/>
<node CREATED="1285861267278" FOLDED="true" ID="Freemind_Link_502876160" MODIFIED="1285861270637" TEXT="Marca">
<node CREATED="1285861271452" ID="Freemind_Link_1251270003" MODIFIED="1285861291702" TEXT="Expresa un concepto del PSM en el PIM"/>
<node CREATED="1285861292529" ID="Freemind_Link_507749340" MODIFIED="1285861334126" TEXT="Puede definir un tipo del modelo, especificar una clase, asociaci&#xf3;n, estereotipo, etc."/>
<node CREATED="1285861343824" FOLDED="true" ID="Freemind_Link_103055946" MODIFIED="1285861402935" TEXT="Pueden especificar caracter&#xed;sticas cualitativas que despu&#xe9;s, en la transformaci&#xf3;n, se convertir&#xe1;n en el objetivo apropiado para el cumplimiento de los requisitos">
<node CREATED="1285861412823" ID="Freemind_Link_1070719665" MODIFIED="1285861597900" TEXT="Podemos marcar aquellos elementos de un modelo que deseemos sean persistentes, o aqu&#xe9;llos que requieran posteriormente mecanismos de seguridad">
<hook NAME="accessories/plugins/NodeNote.properties">
<text>Para comprender este concepto es necesario ver el ejemplo que ofrece el libro.</text>
</hook>
</node>
</node>
<node CREATED="1285861662569" ID="Freemind_Link_305713868" MODIFIED="1285861804551" TEXT="Alejan el PIM de la independencia de la plataforma, por lo que el dise&#xf1;ador debe mantener en la medida de lo posible el PIM &quot;limpio&quot; para posteriormente marcarlo y adaptarlo a una plataforma en concreto"/>
<node CREATED="1285861752353" ID="Freemind_Link_954405705" MODIFIED="1285861772248" TEXT="Se conciben como una capa transparente colocada sobre el modelo"/>
</node>
<node CREATED="1285861828783" FOLDED="true" ID="Freemind_Link_1932192637" MODIFIED="1285861858799" TEXT="La t&#xe9;cnica de marcado no es la &#xfa;nica estrategia posible para llevar a cabo las transformaciones">
<node CREATED="1285861864073" ID="Freemind_Link_1863388390" MODIFIED="1285861887016" TEXT="Este proceso puede estar asistido por el uso de plantillas"/>
<node CREATED="1285861894250" FOLDED="true" ID="Freemind_Link_428516263" MODIFIED="1285861898651" TEXT="Plantilas">
<node CREATED="1285861899556" ID="Freemind_Link_1094729232" MODIFIED="1285861928932" TEXT="Son modelos parametrizados que especifican tipos concretos de transformaciones"/>
<node CREATED="1285861938212" ID="Freemind_Link_8208241" MODIFIED="1285861996477" TEXT="Se puede asociar un conjunto de marcas a una plantilla para identificar instancias en un modelo que deber ser transformadas de acuerdo a la indicaciones de la plantilla"/>
<node CREATED="1285862021230" FOLDED="true" ID="Freemind_Link_948332142" MODIFIED="1285862070152" TEXT="Un elemento en un modelo puede ser marcado varias veces, empleando marcas procedentes de diferentes plantilas">
<node CREATED="1285862083659" ID="Freemind_Link_1752439893" MODIFIED="1285862150523" TEXT="Esos elementos ser&#xe1;n transformados tantas veces como marcas tengan, siguiendo las reglas que especifican las plantillas para lo que fueron marcados"/>
</node>
</node>
</node>
</node>
<node CREATED="1285737434381" ID="Freemind_Link_1949502704" MODIFIED="1285737447998" TEXT="Lenguajes para la definici&#xf3;n de transformaciones"/>
</node>
<node CREATED="1285737486724" ID="Freemind_Link_871270792" MODIFIED="1285737501244" TEXT="El proceso de desarrollo en MDA">
<icon BUILTIN="full-2"/>
</node>
</node>
</node>
<node CREATED="1288566485205" ID="Freemind_Link_693402274" MODIFIED="1288566493605" POSITION="right" TEXT="Gesti&#xf3;n de requerimientos">
<node CREATED="1288568104169" ID="Freemind_Link_974982828" MODIFIED="1288568114280" TEXT="Introducci&#xf3;n">
<node CREATED="1288568133396" ID="Freemind_Link_1113408495" MODIFIED="1288568155331" TEXT="Algunos autores prefieren denominar &quot;ingenier&#xed;a de requisitos&quot;"/>
<node CREATED="1288568180828" ID="Freemind_Link_1111602019" MODIFIED="1288568265756" TEXT="Propone la utilizaci&#xf3;n de t&#xe9;cnicas repetibles y sistem&#xe1;ticas para asegurar la completitud, consistencia y relevancia de los requisitos de un sistema"/>
<node CREATED="1288568311345" ID="Freemind_Link_1436534642" MODIFIED="1288568314592" TEXT="Requisito">
<node CREATED="1288568315768" ID="Freemind_Link_22377492" MODIFIED="1288568369333" TEXT="Una condici&#xf3;n o capacidad necesitada por un  ususario para resolver un problema o alcanzar un objetivo"/>
<node CREATED="1288568392520" ID="Freemind_Link_1145996805" MODIFIED="1288568476466" TEXT="Una condici&#xf3;n o capacidad que un sistema o un componente de un sistema debe satisfacer o poseer de acuerdo con un contrato, est&#xe1;ndar, especificaci&#xf3;n u otro documento impuesto formalmente"/>
<node CREATED="1288568496034" ID="Freemind_Link_817547732" MODIFIED="1288568560729" TEXT="Una representaci&#xf3;n documentada de una condici&#xf3;n o capacidad como en las anteriores afirmaciones"/>
</node>
<node CREATED="1288568615975" ID="Freemind_Link_942499843" MODIFIED="1288568849213" TEXT="En el proceso de ingenier&#xed;a de requisitos se realizan de forma c&#xed;clica las actividades de extracci&#xf3;n, an&#xe1;lisis, especificaci&#xf3;n y verificaci&#xf3;n de los requisitos, adem&#xe1;s de una actividad de gesti&#xf3;n de los requisitos propiamente dicha que se refiere a la programaci&#xf3;n, coordinaci&#xf3;n y documentaci&#xf3;n de la actividades anteriores">
<icon BUILTIN="bell"/>
</node>
<node CREATED="1288568899170" ID="Freemind_Link_168208639" MODIFIED="1288568905287" TEXT="Objetivo b&#xe1;sico">
<node CREATED="1288568906541" ID="Freemind_Link_1312669694" MODIFIED="1288568981852" TEXT="Es la especificaci&#xf3;n de qu&#xe9; debe hacer un sistema y de las restricciones de dise&#xf1;o que condicionan c&#xf3;mo ha de ser implementado"/>
</node>
<node CREATED="1288569022746" ID="Freemind_Link_506810413" MODIFIED="1288569026788" TEXT="Objetivo final">
<node CREATED="1288569028089" ID="Freemind_Link_873236380" MODIFIED="1288569133742" TEXT="Es el desarrollo de un software correcto: en definitiva, un software que hace lo que los clientes quieren que haga">
<node CREATED="1288569228767" ID="Freemind_Link_159667265" MODIFIED="1288569242981" TEXT="Glass (2002)">
<node CREATED="1288569244188" ID="Freemind_Link_496447236" MODIFIED="1288570244726" TEXT="&quot;una de las causas m&#xe1;s comunes de proyectos descontrolados es la inestabilidad de los requisitos&quot;"/>
<node CREATED="1288569292603" FOLDED="true" ID="Freemind_Link_569987389" MODIFIED="1288569346628" TEXT="Destaca este hecho como la causa m&#xe1;s frecuente de proyectos fallidos junto a una inadecuada estimaci&#xf3;n del proyecto en tiempos y costos">
<node CREATED="1288569364761" ID="Freemind_Link_1423609248" MODIFIED="1288569466311" TEXT="El origen de la inestabilidad en los requisitos radica, en la mayor&#xed;a de las ocasiones, en que el cliente o los usuarios no conocen realmente cu&#xe1;les son sus necesidades"/>
</node>
</node>
</node>
</node>
<node CREATED="1288569489342" ID="Freemind_Link_1589043436" MODIFIED="1288569567376" TEXT="Adolece de un problema intr&#xed;nseco de comunicaci&#xf3;n entre aquellas personas que tienen un inter&#xe9;s determinado en un desarrollo de software (los interesados o stakeholders)">
<node CREATED="1288569611639" ID="Freemind_Link_290860897" MODIFIED="1288569706957" TEXT="Tenemos a los directores, a los expertos en marketing y a los usuarios finales de la organizaci&#xf3;n cliente, y por el otro lado, tenemos a los responsables del proyecto y a los desarrolladores del software"/>
</node>
<node CREATED="1288569730285" ID="Freemind_Link_402068758" MODIFIED="1288569741051" TEXT="Ingeniero de requisitos">
<node CREATED="1288569742585" ID="Freemind_Link_315925433" MODIFIED="1288569836676" TEXT="Debe ser capaz de jugar un papel intermedio y especificar todos los requisitos de manera que se transmita al desarrollador de forma completa y no ambigua lo que el cliente desea"/>
<node CREATED="1288569855121" ID="Freemind_Link_595656554" MODIFIED="1288569956321" TEXT="Especificar los requisitos que los clientes son capaces de transmitir por s&#xed; mismos, sino tambi&#xe9;n ayudarles a desarrollar sus requisitos, a extraer necesidades que inicialmente no sospechaban"/>
<node CREATED="1288569999476" ID="Freemind_Link_1105843695" MODIFIED="1288570064702" TEXT="En ocasiones, es preciso adoptar decisiones de compromiso (trade-offs) para reconciliar distintas expectativas de los interesados"/>
</node>
<node CREATED="1288570225274" ID="Freemind_Link_1994151038" MODIFIED="1288570278626" TEXT="Influye decisivamente en el resto de procesos de desarrollo y mantenimiento de un sistema"/>
<node CREATED="1288570289724" ID="Freemind_Link_534441382" MODIFIED="1288570349009" TEXT="No es un proceso qu se realiza s&#xf3;lo en las primeras etapas del desarrollo de un proyecto y produce un conjunto de documentos que quedan congelados"/>
<node CREATED="1288570364543" ID="Freemind_Link_1853434505" MODIFIED="1288570563995" TEXT="Dado que los requisitos son de naturaleza cambiante, de forma inevitable se encuentran sujetos a cambios constantes durante todo el desarrollo: es por tanto necesario gestionar adecuadamente los cambios en los requisitos a lo largo del desarrollo y la explotaci&#xf3;n del software, a trav&#xe9;s de sus relaciones de traza con el resto de los productos de desarrollo  y con los compromisos que se hayan establecido"/>
<node CREATED="1288570614937" ID="Freemind_Link_475202836" MODIFIED="1288570653741" TEXT="La gesti&#xf3;n de requisitos para factor&#xed;as de software se centra en l&#xed;neas de productos"/>
<node CREATED="1288570953481" ID="Freemind_Link_1874623430" MODIFIED="1288571033164" TEXT="El reto fundamental de la gesti&#xf3;n de requisitos para l&#xed;neas de productos es el tratamiento adecuado de la variabilidad de los requisitos"/>
<node CREATED="1288571051682" ID="Freemind_Link_1187420082" MODIFIED="1288571146476" TEXT="La gesti&#xf3;n de requisitos para l&#xed;neas de productos se relaciona habitualmente con el uso de modelos de caracter&#xed;sticas, con extensiones para los modelos de casos de uso, y m&#xe1;s recientemente con modelos de variabilidad independientes"/>
<node CREATED="1288571192254" ID="Freemind_Link_1575484774" MODIFIED="1288571252758" TEXT="La gesti&#xf3;n de requisitos convencional se suele orientar a la gesti&#xf3;n de requisitios textuales y de documentos de requisitos"/>
<node CREATED="1288571261476" ID="Freemind_Link_1849518855" MODIFIED="1288571345750" TEXT="Los conceptos y t&#xe9;cnicas generales de la gesti&#xf3;n de requisitos convencional, son tambi&#xe9;n de utilidad en el campo de las l&#xed;neas de producci&#xf3;n"/>
</node>
<node CREATED="1288571575839" ID="Freemind_Link_17713119" MODIFIED="1288571585051" TEXT="Requisitos y CMMI">
<node CREATED="1288571594521" ID="Freemind_Link_709940254" MODIFIED="1288571597143" TEXT="CMMI">
<node CREATED="1288571598181" ID="Freemind_Link_53007951" MODIFIED="1288571654263" TEXT="Relaciona una serie de principios y pr&#xe1;cticas con la madurez de los procesos en una organizaci&#xf3;n, con el objetivo de introducir progresivamente mejoras tales procesos"/>
</node>
<node CREATED="1288571713741" ID="Freemind_Link_1530067768" MODIFIED="1288571803425" TEXT="Diversos estudios revelan la evidencia de una fuerte relaci&#xf3;n entre un proceso de gesti&#xf3;n de requisitos bien definido y un mejora a corto plazo de la productividad en el proceso de desarrollo"/>
<node CREATED="1288571841809" ID="Freemind_Link_1302673923" MODIFIED="1288571935661" TEXT="Se han definido propuestas de evaluaci&#xf3;n de la madurez del proceso que se centran espec&#xed;ficamente en la mejora de la gesti&#xf3;n de requisitos, pero sin duda la propuesta general de CMMI es m&#xe1;s popular que cualquiera de ellas"/>
<node CREATED="1288572000549" ID="Freemind_Link_496026765" MODIFIED="1288572043822" TEXT="Aunque los requisitos afectan muchas &#xe1;reas de procesos, CMMI define dos expresamente relacionadas con los requisitos:">
<node CREATED="1288572045840" ID="Freemind_Link_1048008167" MODIFIED="1288572106304" TEXT="Gesti&#xf3;n de requisitos (REQM) en el nivel 2">
<node CREATED="1288572375434" ID="Freemind_Link_173555376" MODIFIED="1288572469804" TEXT="Su objetivo fundamental es la gesti&#xf3;n de los requisitos del proyecto y la identificaci&#xf3;n de inconsistencias de los requisitos con los planes del proyecto y con los productos de trabajo del proyecto"/>
<node CREATED="1288572490222" ID="Freemind_Link_740794688" MODIFIED="1288572561044" TEXT="Se trata de obtener un acuerdo sobre le conjunto de requisitos que ser&#xe1;n  implementados y mantener actualizados dicho conjunto de requisitos a lo largo de todo el proyecto"/>
<node CREATED="1288572745711" ID="Freemind_Link_1005655760" MODIFIED="1288572768703" TEXT="Las metas espec&#xed;ficas de esta &#xe1;rea de proceso:">
<node CREATED="1288572597854" ID="Freemind_Link_15359144" MODIFIED="1288572830233" TEXT="Obtener y analizar los requisitos (que CMMI denomina de forma un tanto ambigua &quot;Obtain an Understanding of Requirements&quot;"/>
<node CREATED="1288572834541" ID="Freemind_Link_1697893662" MODIFIED="1288572847365" TEXT="Obtener la aprobaci&#xf3;n de los requisitos"/>
<node CREATED="1288572847763" ID="Freemind_Link_1619369955" MODIFIED="1288572864657" TEXT="Gestionar los cambios de los requisitos"/>
<node CREATED="1288572865135" ID="Freemind_Link_1099686258" MODIFIED="1288572928579" TEXT="Mantener una traza bidireccional de los requisitos entre sus fuentes y los artefactos que se derivan de ellos e identificar inconsistencias entre el desarrollo y los requisitos"/>
</node>
</node>
<node CREATED="1288572066700" ID="Freemind_Link_479470811" MODIFIED="1288572118354" TEXT="Desarrollo de requisitos (RD) en el nivel 3">
<node CREATED="1288572159772" ID="Freemind_Link_1943054443" MODIFIED="1288572189204" TEXT="Para implementar RD es preciso haber institucionalizado REQM"/>
<node CREATED="1288572966737" ID="Freemind_Link_909255042" MODIFIED="1288573060593" TEXT="El objetivo fundamental de RD es analizar los requisitos del cliente y extraer a partir de ellos los requisitos de la aplicaci&#xf3;n o producto que se ha de desarrollar"/>
<node CREATED="1288573091751" ID="Freemind_Link_1730658030" MODIFIED="1288573235087" TEXT="En esta &#xe1;rea de proceso se incluye el an&#xe1;lisis de los requisitos de los clientes, construyendo un modelo del dominio del problema y relacionando los requisitos de los clientes con dicho modelo, para seleccionar y desarrollar los requisitos que han de ser soportados por el producto o aplicaci&#xf3;n"/>
<node CREATED="1288573264085" ID="Freemind_Link_547882767" MODIFIED="1288573345243" TEXT="Despu&#xe9;s se construye una especificaci&#xf3;n de requisitos, es decir, una especificaci&#xf3;n del comportamiento externo del sistema que permita la comprensi&#xf3;n de las funcioines del mismo, que incluya los requisitos de interfaz, y que permita la validaci&#xf3;n de los requisitos"/>
</node>
</node>
<node CREATED="1288572211882" ID="Freemind_Link_996641491" MODIFIED="1288572341076" TEXT="Los requisitos tienen relaci&#xf3;n con otras &#xe1;reas de proceso de CMMI como Planificaci&#xf3;n del Proyecto (PP), Gesti&#xf3;n de Acuerdos con los Proveedores (SAM), Validaci&#xf3;n (VAL), Verificaci&#xf3;n (VER) y Gesti&#xf3;n del Riesgo (RSKM)"/>
</node>
<node CREATED="1288573367663" ID="Freemind_Link_1092613241" MODIFIED="1288573387505" TEXT="T&#xe9;cnicas generales de gesti&#xf3;n de requisitos">
<node CREATED="1288573397894" ID="Freemind_Link_1475688471" MODIFIED="1288573408786" TEXT="Extracci&#xf3;n de requisitos">
<node CREATED="1288584825730" ID="Freemind_Link_864799076" MODIFIED="1288584894092" TEXT="Factores esenciales para que el proyecto se realice con garant&#xed;as de &#xe9;xito:">
<node CREATED="1288584901836" ID="Freemind_Link_1090026889" MODIFIED="1288584983158" TEXT="La correcta identificaci&#xf3;n de interlocutores"/>
<node CREATED="1288584985266" ID="Freemind_Link_1062977616" MODIFIED="1288584991178" TEXT="La adecuada gesti&#xf3;n de los procedimientos para extraer informaci&#xf3;n necesaria"/>
<node CREATED="1288584945962" ID="Freemind_Link_1541115048" MODIFIED="1288585065456" TEXT="El establecimiento de los mecanismos que ayuden a desarrollar las discusiones y posteriores acuerdos en la identificaci&#xf3;n y definici&#xf3;n de los requisitos"/>
</node>
<node CREATED="1288585084828" ID="Freemind_Link_455620471" MODIFIED="1288585108380" TEXT="T&#xe9;cnicas a emplear en la extracci&#xf3;n de requisitos:">
<node CREATED="1288585109522" ID="Freemind_Link_1367857270" MODIFIED="1288585116286" TEXT="Reuniones informales"/>
<node CREATED="1288585118054" ID="Freemind_Link_1638804226" MODIFIED="1288585128304" TEXT="Entrevistas (con o sin cuestionario)"/>
<node CREATED="1288585130832" ID="Freemind_Link_537156241" MODIFIED="1288585140466" TEXT="Mera observaci&#xf3;n"/>
<node CREATED="1288585140944" ID="Freemind_Link_1484081392" MODIFIED="1288585152306" TEXT="Estudio de documentaci&#xf3;n existente"/>
<node CREATED="1288585153314" ID="Freemind_Link_527314093" MODIFIED="1288585193808" TEXT="Reuniones tipo FAST (Facilitated Application Specification Techniques)"/>
<node CREATED="1288585209126" ID="Freemind_Link_637732939" MODIFIED="1288585234438" TEXT="Reuniones tipo JAD (Joint Application Development)"/>
<node CREATED="1288585260056" ID="Freemind_Link_485664989" MODIFIED="1288585285168" TEXT="Reuniones tipo &quot;tormenta de ideas&quot; (brainstorming)"/>
<node CREATED="1288585286786" ID="Freemind_Link_307065640" MODIFIED="1288585304548" TEXT="T&#xe9;cnicas m&#xe1;s sofisticadas basadas en etnograf&#xed;a"/>
</node>
<node CREATED="1288585325816" ID="Freemind_Link_550391979" MODIFIED="1288585362878" TEXT="En combinaci&#xf3;n con las t&#xe9;cnicas anteriores se pueden usar prototipos para ayudar a extraer requisitos"/>
<node CREATED="1288585371586" ID="Freemind_Link_783237717" MODIFIED="1288585397158" TEXT="El prototipo puede ayudar a conseguir los siguientes beneficios:">
<node CREATED="1288585398206" ID="Freemind_Link_318897067" MODIFIED="1288585447758" TEXT="Permite construir r&#xe1;pidamente los dise&#xf1;os de las pantallas e informes, incluso interactivamente con los usuarios, permitiendo visualizar claramente los formatos del sistema final"/>
<node CREATED="1288585449076" ID="Freemind_Link_189964887" MODIFIED="1288585507098" TEXT="Mejora la comunicaci&#xf3;n entre los usuarios y el equipo de desarrollo de software"/>
<node CREATED="1288585513536" ID="Freemind_Link_797652216" MODIFIED="1288585573728" TEXT="Acelera la construcci&#xf3;n del sistema definitivo, ya que es m&#xe1;s f&#xe1;cil construir un software operativo partiendo de un modelo visible que de unas especificaciones sobre el papel"/>
<node CREATED="1288585574676" ID="Freemind_Link_462297629" MODIFIED="1288585642028" TEXT="Absorbe muchos de los nuevos requisitos que se le ocurren al usuario. No s&#xf3;lo ayuda a producir respuestas, sino tambi&#xe9;n preguntas"/>
<node CREATED="1288585642916" ID="Freemind_Link_1294310004" MODIFIED="1288585684660" TEXT="Un documento de requisitos basado en un prototipo tiende a experimentar menos cambios, acortando as&#xed; el tiempo de desarrollo"/>
</node>
</node>
<node CREATED="1288573409594" ID="Freemind_Link_929755460" MODIFIED="1288573417336" TEXT="Documentaci&#xf3;n de requisitos">
<node CREATED="1288585744874" ID="Freemind_Link_957650034" MODIFIED="1288585789836" TEXT="Uno de los objetivos esenciales de la aplicaci&#xf3;n de un proceso de gesti&#xf3;n de requisitos es la consecuci&#xf3;n de una documentaci&#xf3;n de requisitos de calidad"/>
<node CREATED="1288585817936" ID="Freemind_Link_1222384508" MODIFIED="1288585839320" TEXT="Se presenta la documentaci&#xf3;n desde 3 puntos de vista:">
<node CREATED="1288585840468" ID="Freemind_Link_1045483162" MODIFIED="1288586181508" TEXT="La especificaci&#xf3;n de los requisitos en la documentaci&#xf3;n de requisitos">
<hook NAME="accessories/plugins/NodeNote.properties">
<text>La documentaci&#xf3;n o especificaci&#xf3;n de los distintos tipos de requisitos</text>
</hook>
<node CREATED="1288586184846" ID="Freemind_Link_1513174501" MODIFIED="1288586228138" TEXT="Se han propuesto muchas taxonom&#xed;as sobre tipos de requisitos"/>
<node CREATED="1288586228806" ID="Freemind_Link_672287184" MODIFIED="1288586349885" TEXT="Existe un consenso en que la documentaci&#xf3;n de los requisitos debe proporcionar:">
<node CREATED="1288586279708" ID="Freemind_Link_1947889480" MODIFIED="1288586290720" TEXT="Los requisitos funcionales">
<node CREATED="1288586291648" ID="Freemind_Link_942297100" MODIFIED="1288586375607" TEXT="Los requisitos relativos a las capacidades y servicios que el sistema o el software debe proporcionar"/>
</node>
<node CREATED="1288586404575" ID="Freemind_Link_1945642813" MODIFIED="1288586412287" TEXT="Los requisitos no funcionales">
<node CREATED="1288586413255" FOLDED="true" ID="Freemind_Link_1518774792" MODIFIED="1288586452517" TEXT="Relativos a los atributos de calidad del sistema o del software mientras desempe&#xf1;a sus funciones">
<node CREATED="1288586454145" ID="Freemind_Link_71864207" MODIFIED="1288586463837" TEXT="Rendimiento"/>
<node CREATED="1288586464165" ID="Freemind_Link_1408894907" MODIFIED="1288586470417" TEXT="Disponibilidad"/>
<node CREATED="1288586471525" ID="Freemind_Link_999949957" MODIFIED="1288586474527" TEXT="Portabilidad"/>
<node CREATED="1288586474835" ID="Freemind_Link_1015083843" MODIFIED="1288586479807" TEXT="Seguridad"/>
</node>
</node>
<node CREATED="1288586485605" ID="Freemind_Link_782949284" MODIFIED="1288586494397" TEXT="Las restricciones de dise&#xf1;o">
<node CREATED="1288586495975" ID="Freemind_Link_799135492" MODIFIED="1288586540617" TEXT="Son los condicionamientos existentes para el dise&#xf1;o (pero que no deben ser una anticipaci&#xf3;n del mismo)"/>
</node>
</node>
<node CREATED="1288586674767" ID="Freemind_Link_1276265775" MODIFIED="1288586745309" TEXT="La especificaci&#xf3;n de los requisitos se realiza habitualmente en forma textual mediante lenguaje natural, puede complementarse con tablas, figuras o expresiones matem&#xe1;ticas (f&#xf3;rmulas o expresionas l&#xf3;gicas)"/>
<node CREATED="1288586781377" ID="Freemind_Link_422924477" MODIFIED="1288586958713" TEXT="En ocasiones para especificar los requisitos tambi&#xe9;n se usan:">
<node CREATED="1288586942311" ID="Freemind_Link_1431553588" MODIFIED="1288586948933" TEXT="Diagramas de casos de uso">
<node CREATED="1288586867311" ID="Freemind_Link_1280669474" MODIFIED="1288586912823" TEXT="Que juegan un papel complementario dentro del modelo de casos de uso, que es de naturaleza fundamentalmente textual)"/>
</node>
<node CREATED="1288586964551" ID="Freemind_Link_335917381" MODIFIED="1288586972033" TEXT="Modelos de datos">
<node CREATED="1288586976041" ID="Freemind_Link_255199994" MODIFIED="1288586986523" TEXT="Diagramas entidad-relaci&#xf3;n"/>
</node>
<node CREATED="1288586998741" ID="Freemind_Link_1688543425" MODIFIED="1288587011113" TEXT="Diagramas de clases UML"/>
<node CREATED="1288587011651" ID="Freemind_Link_960450073" MODIFIED="1288587030633" TEXT="Modelos de procesos">
<node CREATED="1288587031771" ID="Freemind_Link_1875538913" MODIFIED="1288587049733" TEXT="Diagramas de flujo de datos"/>
<node CREATED="1288587050961" ID="Freemind_Link_433563928" MODIFIED="1288587059133" TEXT="Diagramas de actividad UML"/>
</node>
<node CREATED="1288587077991" ID="Freemind_Link_1336056900" MODIFIED="1288587089935" TEXT="Modelos de comportamiento">
<node CREATED="1288587090883" ID="Freemind_Link_1989391758" MODIFIED="1288587099135" TEXT="M&#xe1;quinas de estado UML"/>
</node>
</node>
<node CREATED="1288587110443" ID="Freemind_Link_490997763" MODIFIED="1288587152495" TEXT="En ocasiones el lenguaje natural es sustituido completamente en la especificaci&#xf3;n de los requisitos por alguna o algunas de estas representaciones"/>
<node CREATED="1288587169163" ID="Freemind_Link_1179183637" MODIFIED="1288587241595" TEXT="Si el objetivo del proyecto es alcanzar cierto grado de automatizaci&#xf3;n en la generaci&#xf3;n de software o bien trabajar con sistemas empotrados o cr&#xed;ticos en alg&#xfa;n sentido, se hace necesaria la representaci&#xf3;n formal de los requisitos"/>
<node CREATED="1288587273695" ID="Freemind_Link_1580834228" MODIFIED="1288587364921" TEXT="El lenguaje natural se prefiere ampliamente para la especificaci&#xf3;n y reutilizaci&#xf3;n de requisitos en proyectos de sistemas de informaci&#xf3;n que involucran cuestiones meramente gerenciales o comerciales"/>
<node CREATED="1288587390619" FOLDED="true" ID="Freemind_Link_570901469" MODIFIED="1288587438763" TEXT="El lenguaje natural es la forma de representaci&#xf3;n de requisitos m&#xe1;s usada  por los principales normas de esta materia, como:">
<node CREATED="1288587439931" ID="Freemind_Link_135480222" MODIFIED="1288588280715" TEXT="La Gu&#xed;a para el desarrollo de especificaciones de requisitos de sistema, IEEE 1233 (1999b)"/>
<node CREATED="1288587488883" ID="Freemind_Link_884316116" MODIFIED="1288587543045" TEXT="Pr&#xe1;ctica recomendada para especificaciones de requisitos de software, IEEE 830 (1999a)"/>
</node>
<node CREATED="1288587582423" ID="Freemind_Link_399728459" MODIFIED="1288587653797" TEXT="Muchos interesados en el proyecto no t&#xe9;cnicos prefieren el lenguaje natural, dado que facilita la lectura, an&#xe1;lisis y tratamiento de los mismos, y por tanto favorece la participaci&#xf3;n"/>
<node CREATED="1288587666465" FOLDED="true" ID="Freemind_Link_1323325408" MODIFIED="1288587740079" TEXT="Para escribir buenos requisitos y evitar la ambig&#xfc;edad inherente al lenguaje natural se suele usar una especie de estilo contractural para escribir los requisitos">
<node CREATED="1288587743047" ID="Freemind_Link_1860303284" MODIFIED="1288587795051" TEXT="Pueden utilizar las recomendaciones proporcionadas por las 2 normas de la IEEE ya mencionadas"/>
</node>
<node CREATED="1288587824649" ID="Freemind_Link_640865879" MODIFIED="1288587943085" TEXT="David (2005), concluye que el uso combinado de modelos y de listas de requisitos es una buena pr&#xe1;ctica para mejorar el proceso de gesti&#xf3;n de requisitos">
<node CREATED="1288587953503" ID="Freemind_Link_233714002" MODIFIED="1288588004717" TEXT="Las t&#xe9;cnicas de modelado son expresivas y facilitan la especificaci&#xf3;n y comprensi&#xf3;n de los requisitos"/>
<node CREATED="1288588016865" ID="Freemind_Link_515676281" MODIFIED="1288588090419" TEXT="Las listas de requisitos proporcionan un contrato entre clientes y desarrolladores y facilitan la gesti&#xf3;n de los requisitos del proyecto, clarificando el tama&#xf1;o del mismo y el estado actual de desarrollo de los requisitos"/>
</node>
<node CREATED="1288588115741" ID="Freemind_Link_1455994251" MODIFIED="1288588158625" TEXT="Los requisitos pueden incluir atributos, que proporcionan una &#xfa;til meta-informaci&#xf3;n sobre cada requisito">
<node CREATED="1288588159993" ID="Freemind_Link_586072127" MODIFIED="1288588280725" TEXT="La Norma IEEE 1233 (1999a) recomienda atributos para los requisitos como identificaci&#xf3;n (&#xfa;nica para cada requisito), prioridad, criticidad, viabilidad, riesgo y fuente">
<arrowlink DESTINATION="Freemind_Link_135480222" ENDARROW="Default" ENDINCLINATION="242;0;" ID="Freemind_Arrow_Link_1903212052" STARTARROW="None" STARTINCLINATION="242;0;"/>
</node>
</node>
<node CREATED="1288588314623" ID="Freemind_Link_1022682785" MODIFIED="1288588359135" TEXT="Un tipo de meta-informaci&#xf3;n particularmente interesante sobre los requisitos procede de la noci&#xf3;n de trazabilidad">
<node CREATED="1288588369023" ID="Freemind_Link_764003570" MODIFIED="1288588474525" TEXT="Seguiendo el est&#xe1;ndar IEEE 830 (1999a), la trazabilidad se refiere a la claridad para determinar el origen de cada requisito y a la facilidad de referenciar cada requisito en el desarrollo futuro o en la documentaci&#xf3;n mejorada"/>
<node CREATED="1288588475873" ID="Freemind_Link_1231229150" MODIFIED="1288588555447" TEXT="La trazabilidad tambi&#xe9;n se suele definir como la capacidad de describir y seguir la pista de la vida de un requisito en dos direcciones: hacia delante y hacia atr&#xe1;s"/>
<node CREATED="1288588577475" ID="Freemind_Link_738700020" MODIFIED="1288588700175" TEXT="Mediante las relaciones de traza se puede comprender toda la vida de un requisito, desde su origen, a trav&#xe9;s de su desarrollo y especificaci&#xf3;n, hasta su despliegue y uso. incluyendo su refinamiento">
<hook NAME="accessories/plugins/NodeNote.properties">
<text>Una referencia clave sobre trazabilidad es la de Ramesh y Jarke (2001)</text>
</hook>
</node>
</node>
</node>
<node CREATED="1288585861278" ID="Freemind_Link_572090003" MODIFIED="1288585976464" TEXT="La estructura del Documento de Requisitos del Proyecto (PRD, Project Requirements Document)">
<node CREATED="1288585976402" ID="Freemind_Link_650921484" MODIFIED="1288586026554" TEXT="PRD puede estar constituido por un conjunto de documentos de requisitos relacionados jer&#xe1;rquicamente"/>
</node>
<node CREATED="1288586032372" ID="Freemind_Link_604202103" MODIFIED="1288586063664" TEXT="La estructura interna o plantilla de cada uno de los documentos de requisitos que componen el PRD"/>
</node>
</node>
</node>
</node>
</node>
</map>
